        if inp[j] != outp[j]:
            diff_pos = j
            break

    if diff_pos == -1:
        if len(inp) != len(outp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")
        else:
            print("  No difference found")
    else:
        print(f"  First difference at position {diff_pos}")
        print(f"  Input char: '{inp[diff_pos]}' -> Output char: '{outp[diff_pos]}'")

    print()

