    pos = -1
    for i in range(min_len):
        if inp[i] != outp[i]:
            pos = i
            break

    if pos == -1:
        if len(inp) < len(outp):
            print(f"  Insertion: added '{outp[len(inp)]}' at end")
        elif len(inp) > len(outp):
            print(f"  Deletion: removed '{inp[len(outp)]}' at end")
    else:
        print(f"  Position {pos}: '{inp[pos]}' -> '{outp[pos]}'")

    print()

