    print(f"Example {i}: '{inp}' -> '{outp}'")

    # Find where differences occur
    if len(inp) <= len(outp):
        # Look for insertion pattern
        j = 0
        while j < len(inp) and inp[j] == outp[j]:
            j += 1

        if j < len(inp):
            print(f"  Change at position {j}: '{inp[j]}' -> '{outp[j]}'")
        else:
            # All characters matched up to inp length, so insertion occurred
            print(f"  Insertions: '{outp[len(inp):]}'")
    else:
        print(f"  Deletion detected")
    print()

